SELECT DISTINCT
       o.id, o.user_id, o.`status`, o.total_amount,
       o.category_id, o.category_name, o.create_time, o.update_time
FROM tb_order o

    INNER JOIN tb_order_item oi ON o.id = oi.order_id



        AND o.create_time >= #{startTime}


        AND o.create_time <= #{endTime}


        AND o.total_amount >= #{minAmount}


        AND MATCH(oi.product_name) AGAINST(#{productName} IN BOOLEAN MODE)


        AND (o.create_time < #{cursor}
             OR (o.create_time = #{cursor} AND o.id < #{lastId}))


ORDER BY o.create_time DESC, o.id DESC
LIMIT #{pageSize}

SELECT id, user_id, `status`, total_amount,
       category_id, category_name, create_time, update_time
FROM tb_order


        AND user_id = #{userId}


        AND `status` IN

            #{s}



        AND category_id IN

            #{c}



        AND (create_time < #{cursor}
             OR (create_time = #{cursor} AND id < #{lastId}))


ORDER BY create_time DESC, id DESC
LIMIT #{pageSize}

SELECT id, user_id, `status`, total_amount,
       category_id, category_name, create_time, update_time
FROM tb_order
WHERE user_id = #{userId}

    AND `status` = #{status}

ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM tb_order
WHERE user_id = #{userId}

    AND `status` = #{status}
